 return dict(id='per-'+id,name=name,recommendation=recommendation,scope='One institutional library system; branches are not separate targets.' if id!='mali' else 'One museum research library.',size=sz,platform={'family':family,'name':family,'proof':'Koha branding/routes in returned HTML' if family=='Koha' else 'Quibuk title in homepage; public JavaScript specifies biblios/items handlers.','evidence_path':f'evidence/{q}.html'},query={'text':'Jose Gil de Castro' if id=='mali' else 'Cien años de soledad' if id=='unsm' else 'Cien anos de soledad','method':m['method'],'url':m['url'],'payload':m['payload'],'checked_at_utc':m['checked_at_utc'],'http_status':m['status'],'effective_url':m['effective_url'],'result_count':{'uncp':9,'unsch':14,'unsa':9,'unsm':1,'mali':20}[id],'count_note':'Whole response count, including related records; only example edition below certified.','match_type':'related_titles' if id=='mali' else 'exact_title','evidence_path':m['evidence_path'],'metadata_path':m['metadata_path']},books=[book],robots={'url':r['url'],'status':r['status'],'checked_at_utc':r['checked_at_utc'],'evidence_path':f'evidence/{robots}.json','decision':a['decision'],'note':a['note']},reader_access=access,integration={'existing_adapter':'candidate reuse' if family=='Koha' else 'new family','needs':['Preserve exact edition/record identity and Spanish metadata','Distinguish print, reference-only copies and electronic resources','Confirm policy/reuse and visitor eligibility before product launch'],'blockers':['No live app integration tested']+(['Official endpoint uses HTTP port8009; transport and hosting compatibility require review'] if id=='unsa' else []),'live_app_tested':False})
